{
  "technical_and_design_decisions": [
    "Use Spring XD's existing MessageBus abstraction (Redis, RabbitMQ, Kafka) for queue/topic lifecycle management.",
    "Store deployment properties in the existing repository (ZooKeeper/etcd) and extend the schema to support trace and side-channel properties.",
    "Implement wiretap tracing via Spring Integration's WireTap channel interceptor, configured dynamically at module deployment time based on deployment properties.",
    "Support wildcard module trace property (module.*.trace) by applying interceptors to all modules in the stream during deployment.",
    "Model side channels as additional Spring Integration channels in the module's application context, created on the message bus at deployment time.",
    "Provide reference architectures as pre-packaged Spring XD module repositories with documentation in AsciiDoc.",
    "Implement DEBS 2015 taxi trips analytics using Spring XD's built-in analytics modules (windowing, aggregation) and custom processors for domain-specific logic.",
    "Stream deployment property updates for deployed streams will trigger a rolling redeployment of affected modules to apply new properties without full stream destruction."
  ],
  "assumptions": [
    "Existing Spring XD 1.3.x codebase is available and familiar to the developer.",
    "Message bus implementations (RabbitMQ, Kafka) are installed and configurable for integration testing.",
    "Single developer with strong expertise in Spring Integration, Spring Boot, and Spring XD internals.",
    "CI/CD pipeline exists for building, unit testing, and integration testing.",
    "Unit test coverage target of 80% for new code.",
    "Documentation is maintained in AsciiDoc and published with the project.",
    "Stream destroy operation currently only undeploys modules but does not clean up message bus resources.",
    "Deployment manifest files are in YAML or JSON format, accessible via file:, classpath:, or http: URIs.",
    "Side channels are declared in the module definition metadata (e.g., module.yml).",
    "Reference architectures are limited to 3-4 domain-specific examples (IoT, log analytics, clickstream, taxi trips)."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Stream Resource Cleanup on Destroy",
      "activity_description": "Modify stream destroy lifecycle to delete message bus resources (queues, topics, exchanges) for each module's input/output channels using MessageBus API. Handle errors and idempotency.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A2",
      "activity_name": "Stale Resource Cleanup Job",
      "activity_description": "Implement a scheduled background job that scans the message bus for orphaned queues/topics not associated with any active stream and removes them. Support multiple message bus types.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A3",
      "activity_name": "Stream Deployment Property Update",
      "activity_description": "Enable updating deployment properties for both deployed and undeployed streams without destruction. For deployed streams, implement rolling redeployment of modules with new properties. Update shell and REST APIs.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A4",
      "activity_name": "Deployment Manifest File Support",
      "activity_description": "Add parsing of YAML/JSON deployment manifest files, merge with inline properties, support file/classpath/http URIs. Integrate with stream deploy shell command and REST endpoint.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A5",
      "activity_name": "Trace/Wiretap Deployment Properties",
      "activity_description": "Implement deployment properties 'module.<name>.trace' and 'module.*.trace'. At module deployment, add WireTap channel interceptors to input/output channels, routing copies to a dedicated trace channel per stream.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A6",
      "activity_name": "Wildcard Trace Support",
      "activity_description": "Extend trace property parsing to support wildcard 'module.*.trace' and apply wiretap interceptors to all modules in the stream. Validate wildcard syntax and ensure no conflicts with explicit module traces.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7",
      "activity_name": "Side Channels / Tap Channels",
      "activity_description": "Extend module definition metadata to declare arbitrary side channels. At deployment, create these channels on the message bus. Provide API for modules to publish/consume from side channels. Integrate with module deployment lifecycle.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A8",
      "activity_name": "Reference Architectures and Samples",
      "activity_description": "Create 3-4 reference architecture samples (e.g., IoT, log analytics, clickstream, taxi trips) with stream definitions, custom modules, deployment guides, and architecture diagrams. Package as module repositories.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A9",
      "activity_name": "DEBS 2015 Taxi Trips Analytics Stream",
      "activity_description": "Implement end-to-end stream for NYC taxi trip data ingestion, real-time analytics (trip duration, fare, distance aggregations), and sink to database/dashboard. Use Spring XD analytics modules and custom processors. Document evaluation results.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A10",
      "activity_name": "Integration and End-to-End Testing",
      "activity_description": "Perform integration testing across all new features with RabbitMQ and Kafka message buses, local and distributed deployment modes. Test stream create/deploy/update/destroy cycles, trace/wiretap, side channels, and manifest files.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A11",
      "activity_name": "Documentation and User Guide Updates",
      "activity_description": "Update user guide, REST API documentation, shell command help, and developer guide for all new features. Include examples for trace, side channels, manifest files, and stream update.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A12",
      "activity_name": "Code Review, Refactoring, and Bug Fixes",
      "activity_description": "Conduct self-code reviews, refactor for consistency with Spring XD coding standards, fix bugs found during testing, and ensure backward compatibility.",
      "most_likely_effort": 3
    }
  ],
  "reported_total": {
    "most_likely_effort": 47
  }
}

